// Met en forme le message Discord à partir de la réponse du site.
const d = $input.first().json;

// Un nom comme « Kael_le_Brave » ne doit pas passer en italique.
const escape = (text) => String(text).replace(/([\\*_~`|>\[\]()])/g, '\\$1');
const essais = (n) => `${n} essai${n > 1 ? 's' : ''}`;

let content = `🧩 **Le Lastdle n°${d.day} est disponible !**\nQui se cache derrière le personnage du jour ? ${d.url}`;
if (d.booster) content += '\n🎁 Le trouver rapporte un booster.';

// Un embed vide est ignoré par le nœud Discord : pas de réponse de la veille si personne n'a joué.
let embed = {};
const y = d.yesterday;
if (y) {
  const lines = [`Il fallait trouver **[${escape(y.name)}](${y.url})**.`];
  if (y.winners === 0) lines.push('Personne ne l\'a trouvé.');
  else lines.push(`${y.winners} joueur${y.winners > 1 ? 's l\'ont' : ' l\'a'} trouvé.`);
  if (y.best) lines.push(`🏆 ${y.best.name ? escape(y.best.name) : "Un joueur"}, en ${essais(y.best.tries)} (${y.best.time})`);
  embed = {
    title: `Réponse du Lastdle n°${y.day}`,
    description: lines.join('\n'),
    color: 0xe5b8cc,
    // Simple adresse : le nœud Discord la range lui-même dans { url }.
    thumbnail: y.image
  };
}

return [{ json: { content, embed } }];
